/**
 * Loads the frozen gw2combat Willbender reference encounter for the new engine.
 *
 * The JSON and CSV files beside this module are byte-for-byte copies from the
 * pinned upstream revision (see README.md). Loading applies two explicit,
 * reviewed transformations so nothing is silently changed:
 *
 * - Errata: keys the upstream parser ignores are removed by exact path. The
 *   engine rejects unknown keys, and removing them reproduces what the C++
 *   reference actually simulates. Each path must exist, so fixture drift fails.
 * - The deterministic variant forces every random draw site to a fixed outcome
 *   (100% critical chance, an always-successful lifesteal roll) so C++ and
 *   TypeScript runs can be compared event by event.
 */
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { resolveUpstreamEncounter } from '#gw2/platform/combat-engine/configuration.js';

export const REFERENCE_FIXTURE_DIR = path.dirname(fileURLToPath(import.meta.url));

/** Recorded C++ reference results, regenerated by the comparison script. */
export function readReferenceResults() {
  return JSON.parse(readFileSync(path.join(REFERENCE_FIXTURE_DIR, 'reference-results.json'), 'utf8'));
}

/** Keys present in the upstream build that the upstream parser ignores (effect applications have no stacking type). */
export const IGNORED_UPSTREAM_KEYS = Object.freeze([
  ['skills', 16, 'on_pulse_effect_applications', 0, 'stacking_type'],
  ['skills', 17, 'on_pulse_effect_applications', 0, 'stacking_type'],
  ['skills', 17, 'on_pulse_effect_applications', 1, 'stacking_type'],
  ['skills', 18, 'on_pulse_effect_applications', 0, 'stacking_type'],
  ['skills', 18, 'on_pulse_effect_applications', 1, 'stacking_type'],
  ['skills', 19, 'on_strike_effect_applications', 0, 'stacking_type']
]);

const PLAYER_BUILD = 'build-cwb-pt-pp-skill-ticks.json';

function removeIgnoredKeys(build) {
  for (const keyPath of IGNORED_UPSTREAM_KEYS) {
    const parent = keyPath.slice(0, -1).reduce((node, segment) => node?.[segment], build);
    const key = keyPath.at(-1);
    if (parent == null || !Object.hasOwn(parent, key)) {
      throw new Error(`Reference erratum ${keyPath.join('.')} no longer matches the fixture.`);
    }

    delete parent[key];
  }
}

/** Collects every object in a JSON tree matching a predicate. */
function findObjects(node, predicate, found = []) {
  if (Array.isArray(node)) {
    for (const item of node) findObjects(item, predicate, found);
  } else if (node != null && typeof node === 'object') {
    if (predicate(node)) found.push(node);
    for (const value of Object.values(node)) findObjects(value, predicate, found);
  }

  return found;
}

/** Forces the build's random draw sites to fixed outcomes; exported so the C++ comparison uses the identical input. */
export function makeDeterministic(build) {
  build.attributes.push(['critical_chance_multiplier', 1.0]);
  const randomThresholds = findObjects(build, (node) => node.generate_random_number_subject_to_threshold === true);
  if (randomThresholds.length !== 1) {
    throw new Error(`Expected one random threshold in the reference build, found ${randomThresholds.length}.`);
  }

  // A uniform draw in [0, 100) is always below 101.
  randomThresholds[0].threshold_value = 101;
  return build;
}

/** Reads a fixture file, applying errata (and the deterministic variant) to the player build. */
export function readReferenceFile(file, { deterministic = false } = {}) {
  const text = readFileSync(path.join(REFERENCE_FIXTURE_DIR, file), 'utf8');
  if (file !== PLAYER_BUILD) return text;
  const build = JSON.parse(text);
  removeIgnoredKeys(build);
  return JSON.stringify(deterministic ? makeDeterministic(build) : build);
}

/** Returns the reference encounter with inline builds and rotations, ready for `runCombatEngine`. */
export function loadReferenceEncounter({ deterministic = false } = {}) {
  const local = JSON.parse(readFileSync(path.join(REFERENCE_FIXTURE_DIR, 'encounter.json'), 'utf8'));
  // Upstream paths are relative to its repository root; the fixture keeps only file names.
  return resolveUpstreamEncounter(local, (file) => readReferenceFile(path.basename(file), { deterministic }));
}
